import * as z from "zod/v4";
import { defineTool } from "../../../tools.js";
import extension from "../extension.js";
import { assertWriteChannel } from "../lib/channels.js";
import { launchCloudAgent } from "../lib/launch-agent.js";
import { launchRepos } from "../lib/repos.js";
const launch = defineTool({
    description: "Launch a Cursor cloud agent on a repository with a self-contained task. Returns the agent id and URL, and watching: true when this conversation will be woken once the agent stops; check on it with get, read what it did with dump.",
    effect: "write",
    needsApproval: () => extension.config.needsApproval,
    inputSchema: z.object({
        prompt: z
            .string()
            .min(1)
            .describe("Self-contained task: goal, constraints, and what done looks like."),
        repo: z
            .string()
            .url()
            .optional()
            .describe("Repository clone URL (GitHub or Origin), one of the configured repositories. Defaults to the configured repository when there is exactly one."),
        starting_ref: z
            .string()
            .optional()
            .describe("Branch or commit to start from; defaults to the configured or default branch."),
        pr_url: z
            .string()
            .url()
            .optional()
            .describe("Work on this pull request's branch instead of a new one."),
        name: z
            .string()
            .max(100)
            .optional()
            .describe("Display name; derived from the prompt when omitted."),
    }),
    async execute(input, ctx) {
        assertWriteChannel(ctx);
        const { cloud } = extension.config;
        return launchCloudAgent(ctx, {
            prompt: input.prompt,
            name: input.name,
            cloud: {
                ...cloud,
                repos: launchRepos({ repo: input.repo, ref: input.starting_ref, prUrl: input.pr_url }, cloud),
            },
        });
    },
});
export default launch;
